const entradaOriginal =
  $('Entrada Observatorio').first().json || {};

const salida = JSON.parse(
  JSON.stringify(entradaOriginal)
);

const aviso = JSON.parse(
  JSON.stringify(salida.__aviso || {})
);

try {
  const cargaConfirmada =
    $('Resolver periodo encabezados').first().json || {};

  const camposCargados = Object.keys(cargaConfirmada)
    .filter(campo =>
      campo !== 'PERIODO' &&
      !campo.startsWith('__')
    );

  const esCargaICC = camposCargados.some(
    campo =>
      String(campo)
        .toLowerCase()
        .includes('confianza del consumidor')
  );

  if (
    esCargaICC &&
    Array.isArray(aviso.cargas)
  ) {
    for (const carga of aviso.cargas) {
      const nombre = String(
        carga.nombre || carga.fuente || ''
      ).toLowerCase();

      if (
        nombre.includes('icc') ||
        nombre.includes('confianza del consumidor')
      ) {
        /*
         * Seis datos originales más el acumulado
         * calculado en Resolver periodo encabezados.
         */
        carga.columnas_enviadas =
          camposCargados.length;

        carga.columnas_esperadas = 7;

        carga.celdas_actualizadas =
          camposCargados.length;

        carga.columnas_faltantes =
          camposCargados.length < 7
            ? [`Faltan ${7 - camposCargados.length} campos`]
            : [];
      }
    }
  }
} catch (error) {
  /*
   * Este nodo también recibe las ramas de aviso
   * y de indicadores productivos. En esas ramas
   * Resolver periodo encabezados no fue ejecutado.
   */
}

salida.__aviso = aviso;
salida.__carga_correcta = true;

return [
  {
    json: salida
  }
];

const carga = $('Es productivo').first().json;
const filas = $input.all().map(item => item.json);

if (!carga.__periodo) {
  throw new Error('No se recibió el período productivo');
}

const partes = String(carga.__periodo)
  .slice(0, 10)
  .split('-');

const anioBuscado = Number(partes[0]);
const mesNumero = Number(partes[1]);

const mesesLargos = [
  'ENERO', 'FEBRERO', 'MARZO', 'ABRIL',
  'MAYO', 'JUNIO', 'JULIO', 'AGOSTO',
  'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'
];

const mesesCortos = [
  'ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN',
  'JUL', 'AGO', 'SEP', 'OCT', 'NOV', 'DIC'
];

const mesBuscado = mesesLargos[mesNumero - 1];
const periodoPecuario =
  `${mesesCortos[mesNumero - 1]} ${String(anioBuscado).slice(-2)}`;

if (!Number.isInteger(anioBuscado) || !mesBuscado) {
  throw new Error(`Período inválido: ${carga.__periodo}`);
}

const normalizar = valor => String(valor ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/SEPT/g, 'SEP')
  .replace(/[-_/]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toUpperCase();

const esPecuaria = Object.keys(carga).some(
  campo => normalizar(campo) === 'PERIODO'
);

let filaEncontrada = null;

if (esPecuaria) {
  // Pecuaria: busca exclusivamente su columna “Periodo”.
  for (const fila of filas) {
    const camposPeriodo = Object.entries(fila)
      .filter(([campo]) =>
        normalizar(campo) === 'PERIODO' ||
        normalizar(campo).startsWith('PERIODO ')
      )
      .map(([, valor]) => normalizar(valor));

    if (camposPeriodo.includes(normalizar(periodoPecuario))) {
      filaEncontrada = fila;
      break;
    }
  }
} else {
  // Comercialización: conserva su estructura Año/Mes en A:B.
  let anioActual = null;

  for (const fila of filas) {
    const valor = normalizar(
      fila['Año/Mes'] ??
      fila['Año/Mes_2'] ??
      ''
    );

    if (/^\d{4}$/.test(valor)) {
      anioActual = Number(valor);
      continue;
    }

    if (
      anioActual === anioBuscado &&
      valor === mesBuscado
    ) {
      filaEncontrada = fila;
      break;
    }
  }
}

if (!filaEncontrada) {
  throw new Error(
    esPecuaria
      ? `No se encontró ${periodoPecuario} en el bloque pecuario`
      : `No se encontró ${mesBuscado} de ${anioBuscado} en comercialización`
  );
}

const filaReal = Number(filaEncontrada.row_number) + 1;
const filaLocal = Number(carga.__fila_local);

if (!Number.isInteger(filaReal)) {
  throw new Error(
    'Google Sheets no entregó un row_number válido'
  );
}

const diferenciaFilas =
  Number.isInteger(filaLocal)
    ? filaReal - filaLocal
    : 0;
const encabezadosDisponibles = new Set(
  filas.flatMap(fila => Object.keys(fila))
);

const camposDesconocidos = Object.keys(carga).filter(
  campo =>
    !campo.startsWith('__') &&
    campo !== 'row_number' &&
    !encabezadosDisponibles.has(campo)
);

if (camposDesconocidos.length) {
  throw new Error(
    `Campos productivos sin encabezado en el Sheet: ${camposDesconocidos.join(', ')}`
  );
}
const resultado = {};

for (const [campo, valor] of Object.entries(carga)) {
  if (campo.startsWith('__')) continue;

  if (
    typeof valor === 'string' &&
    valor.startsWith('=') &&
    diferenciaFilas !== 0
  ) {
    resultado[campo] = valor.replace(
      /(\$?[A-Z]{1,3})(\$?)(\d+)/g,
      (coincidencia, columna, absoluto, numero) => {
        const filaNueva =
          Number(numero) + diferenciaFilas;

        return `${columna}${absoluto}${filaNueva}`;
      }
    );
  } else {
    resultado[campo] = valor;
  }
}

resultado.row_number = filaReal;

return [{ json: resultado }];

const carga = $('Entrada Observatorio').first().json;
const filas = $input.all().map(item => item.json);

const normalizar = valor => String(valor ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const claveFecha = valor => {
  if (valor === null || valor === undefined || valor === '') {
    return null;
  }

  if (typeof valor === 'number') {
    const fecha = new Date(
      Date.UTC(1899, 11, 30) + Math.round(valor * 86400000)
    );
    return fecha.toISOString().slice(0, 10);
  }

  const original = String(valor).trim();
  const texto = original
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();

  let coincidencia = texto.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (coincidencia) {
    return `${coincidencia[1]}-${String(coincidencia[2]).padStart(2, '0')}-${String(coincidencia[3]).padStart(2, '0')}`;
  }

  coincidencia = texto.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  if (coincidencia) {
    return `${coincidencia[3]}-${String(coincidencia[2]).padStart(2, '0')}-${String(coincidencia[1]).padStart(2, '0')}`;
  }

  const meses = {
    ene: 1, enero: 1, feb: 2, febrero: 2,
    mar: 3, marzo: 3, abr: 4, abril: 4,
    may: 5, mayo: 5, jun: 6, junio: 6,
    jul: 7, julio: 7, ago: 8, agosto: 8,
    sep: 9, sept: 9, septiembre: 9,
    oct: 10, octubre: 10, nov: 11, noviembre: 11,
    dic: 12, diciembre: 12
  };

  coincidencia = texto.match(/^([a-z]+)[\s\-/]+(\d{2}|\d{4})$/);
  if (coincidencia) {
    const mes = meses[coincidencia[1]];
    let anio = Number(coincidencia[2]);
    if (anio < 100) anio += 2000;
    if (mes) return `${anio}-${String(mes).padStart(2, '0')}-01`;
  }

  const fecha = new Date(original);
  return Number.isNaN(fecha.getTime())
    ? null
    : fecha.toISOString().slice(0, 10);
};

const convertirNumero = valor => {
  if (typeof valor === 'number') {
    return Number.isFinite(valor) ? valor : null;
  }

  let texto = String(valor ?? '')
    .trim()
    .replace('%', '')
    .replace(/\s+/g, '');

  if (!texto) return null;

  if (texto.includes(',') && texto.includes('.')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else {
    texto = texto.replace(',', '.');
  }

  const resultado = Number(texto);
  return Number.isFinite(resultado) ? resultado : null;
};

const redondear = valor =>
  Math.round((valor + Number.EPSILON) * 100) / 100;

if (!filas.length) {
  throw new Error('Leer Base no devolvió filas de BASE DE DATOS');
}

const encabezados = [
  ...new Set(filas.flatMap(fila => Object.keys(fila)))
].filter(encabezado => encabezado !== 'row_number');

const mapaEncabezados = new Map(
  encabezados.map(encabezado => [
    normalizar(encabezado),
    encabezado
  ])
);

const encabezadoPeriodo = mapaEncabezados.get(normalizar('PERIODO'));
if (!encabezadoPeriodo) {
  throw new Error('No se encontró el encabezado PERIODO en BASE DE DATOS');
}

const periodoObjetivo = claveFecha(carga.PERIODO);
if (!periodoObjetivo) {
  throw new Error(`Período inválido recibido: ${carga.PERIODO}`);
}

const filaActual = filas.find(
  fila => claveFecha(fila[encabezadoPeriodo]) === periodoObjetivo
);

if (!filaActual) {
  const ejemplos = filas.slice(0, 5)
    .map(fila => String(fila[encabezadoPeriodo] ?? ''))
    .join(', ');
  throw new Error(
    `No se encontró el período ${periodoObjetivo} en BASE DE DATOS. Ejemplos leídos: ${ejemplos}`
  );
}

const equivalencias = new Map([
  [
    normalizar('Índice de Confianza del Consumidor Interior'),
    normalizar('Indice de Confianza del Consumidor por Regiones: Interior')
  ]
]);

const resultado = {};
const omitidos = [];

for (const [campo, valor] of Object.entries(carga)) {
  if (campo.startsWith('__')) continue;
  if (normalizar(campo) === normalizar('PERIODO')) continue;

  const campoBuscado =
    equivalencias.get(normalizar(campo)) || normalizar(campo);

  const coincidencias = encabezados.filter(
    encabezado => normalizar(encabezado) === campoBuscado
  );

  if (coincidencias.length !== 1) {
    omitidos.push(`${campo} (${coincidencias.length} coincidencias)`);
    continue;
  }

  const encabezadoReal = coincidencias[0];
  const existente = filaActual[encabezadoReal];
  const recibido = valor;
  const formula =
    typeof recibido === 'string' && recibido.startsWith('=');

  // Leer Base devuelve el valor calculado de una fórmula.
  // No reemplazar una fórmula existente.
  if (
    formula &&
    existente !== null &&
    existente !== undefined &&
    existente !== ''
  ) {
    continue;
  }

  const mismoTexto =
    String(existente ?? '').trim() === String(recibido ?? '').trim();
  const numeroExistente = convertirNumero(existente);
  const numeroRecibido = convertirNumero(recibido);
  const mismoNumero =
    numeroExistente !== null &&
    numeroRecibido !== null &&
    Math.abs(numeroExistente - numeroRecibido) < 1e-9;

  if (mismoTexto || (!formula && mismoNumero)) continue;
  resultado[encabezadoReal] = valor;
}

/*
 * DNRPA: los ocho datos originales corresponden a patentamientos
 * y transferencias de autos y motos, Formosa y Nación.
 * Las fórmulas existentes del Sheet se conservan.
 */
const gruposDnrpa = [
  [
    'Patentamiento de automóviles F',
    'Patentamiento de automóviles - Acumulado F',
    'Patentamiento de automóviles - Var % intermensual F',
    'Patentamiento de automóviles - Var % interanual F'
  ],
  [
    'Transferencias de automoviles F',
    'Transferencias de automoviles acumulada F',
    'Transferencias de automóviles - Var % intermensual F',
    'Transferencias de automóviles - Var % interanual F'
  ],
  [
    'Patentamiento de automóviles N',
    'Patentamiento de automóviles - Acumulado N',
    'Patentamiento de automóviles - Var % intermensual N',
    'Patentamiento de automóviles - Var % interanual N'
  ],
  [
    'Transferencias de automoviles N',
    'Transferencias de automoviles acumulada N',
    'Transferencias de automóviles - Var % intermensual N',
    'Transferencias de automóviles - Var % interanual N'
  ],
  [
    'Patentamiento de Motos F',
    'Patentamiento de Motos - Acumulado F',
    'Patentamiento de Motos- Var % intermensual F',
    'Patentamiento de Motos- Var % interanual F'
  ],
  [
    'Transferencias de Motos F',
    'Transferencias de Motos - Acumulado F',
    'Transferencias de Motos- Var % intermensual F',
    'Trasnferencias de Motos- Var % interanual F'
  ],
  [
    'Patentamiento de Motos N',
    'Patentamiento de Motos - Acumulado N',
    'Patentamiento de Motos- Var % intermensual N',
    'Trasnferencias de Motos- Var % interanual N'
  ],
  [
    'Transferencias de Motos N',
    'Transferencias de Motos - Acumulado N',
    'Transferencias de Motos- Var % intermensual N',
    'Trasnferencias de Motos- Var % interanual N'
  ]
];

const titulosDnrpa = gruposDnrpa.map(
  grupo => mapaEncabezados.get(normalizar(grupo[0]))
);

const contieneDnrpa = titulosDnrpa.some(
  titulo =>
    titulo &&
    Object.prototype.hasOwnProperty.call(carga, titulo)
);

if (contieneDnrpa) {
  if (titulosDnrpa.some(
    titulo =>
      !titulo ||
      !Object.prototype.hasOwnProperty.call(carga, titulo)
  )) {
    throw new Error(
      'DNRPA: faltan datos originales de alguna de las cuatro consultas; no se carga parcialmente'
    );
  }

  for (const grupo of gruposDnrpa) {
    const titulosReales = grupo.map(titulo => {
      const real = mapaEncabezados.get(normalizar(titulo));
      if (!real) throw new Error(`DNRPA: falta encabezado ${titulo}`);
      return real;
    });

    const posiciones = titulosReales.map(
      titulo => encabezados.indexOf(titulo)
    );

    if (posiciones.some(
      (pos, i) => pos !== posiciones[0] + i
    )) {
      throw new Error(
        `DNRPA: las cuatro columnas de ${grupo[0]} no están contiguas`
      );
    }

    const original = convertirNumero(carga[titulosReales[0]]);
    if (original === null || original <= 0) {
      throw new Error(
        `DNRPA: dato original inválido en ${titulosReales[0]}`
      );
    }

    const cambiaOriginal = Object.prototype.hasOwnProperty.call(
      resultado,
      titulosReales[0]
    );
    if (cambiaOriginal) resultado[titulosReales[0]] = original;

    const actual = 'INDIRECT(ADDRESS(ROW(),COLUMN()-1))';
    const anteriorAcumulado = 'INDIRECT(ADDRESS(ROW()-1,COLUMN()))';
    const mensual = 'INDIRECT(ADDRESS(ROW(),COLUMN()-2))';
    const previoMensual = 'INDIRECT(ADDRESS(ROW()-1,COLUMN()-2))';
    const interanual = 'INDIRECT(ADDRESS(ROW(),COLUMN()-3))';
    const previoInteranual = 'INDIRECT(ADDRESS(ROW()-12,COLUMN()-3))';
    const enero = Number(periodoObjetivo.slice(5, 7)) === 1;

    const formulas = [
      enero
        ? `=${actual}`
        : `=${anteriorAcumulado}+${actual}`,
      `=IFERROR(${mensual}/${previoMensual}*100-100,"")`,
      `=IFERROR(${interanual}/${previoInteranual}*100-100,"")`
    ];

    for (let i = 1; i < 4; i++) {
      const titulo = titulosReales[i];
      const existente = filaActual[titulo];

      // La fórmula existente se recalcula al cambiar el dato original.
      // Solo completar las fórmulas que falten.
      if (
        existente === null ||
        existente === undefined ||
        existente === ''
      ) {
        resultado[titulo] = formulas[i - 1];
      }
    }
  }
}

/* Cálculo del acumulado del ICC Interior. */
const encabezadoMensual = mapaEncabezados.get(
  normalizar(
    'Indice de Confianza del Consumidor Interior Variación respecto al mes anterior'
  )
);

const encabezadoAcumulado = mapaEncabezados.get(
  normalizar(
    'Indice de Confianza del Consumidor Interior Acumulado del año'
  )
);

const esICC =
  encabezadoMensual &&
  Object.prototype.hasOwnProperty.call(
    resultado,
    encabezadoMensual
  );

if (esICC) {
  if (!encabezadoAcumulado) {
    throw new Error(
      'No se encontró la columna del acumulado del ICC Interior'
    );
  }

  const variacionMensual = convertirNumero(
    resultado[encabezadoMensual]
  );

  if (variacionMensual === null) {
    throw new Error(
      'No se pudo interpretar la variación mensual del ICC Interior'
    );
  }

  const fechaActual = new Date(`${periodoObjetivo}T00:00:00Z`);

  if (fechaActual.getUTCMonth() === 0) {
    resultado[encabezadoAcumulado] = redondear(variacionMensual);
  } else {
    fechaActual.setUTCMonth(fechaActual.getUTCMonth() - 1);
    const periodoAnterior = fechaActual.toISOString().slice(0, 10);

    const filaAnterior = filas.find(
      fila => claveFecha(fila[encabezadoPeriodo]) === periodoAnterior
    );

    if (!filaAnterior) {
      throw new Error(
        `No se encontró el período anterior ${periodoAnterior} para calcular el acumulado del ICC`
      );
    }

    const acumuladoAnterior = convertirNumero(
      filaAnterior[encabezadoAcumulado]
    );

    if (acumuladoAnterior === null) {
      throw new Error(
        `El acumulado anterior del ICC está vacío en ${periodoAnterior}`
      );
    }

    resultado[encabezadoAcumulado] = redondear(
      (
        (1 + acumuladoAnterior / 100) *
        (1 + variacionMensual / 100) -
        1
      ) * 100
    );
  }
}

if (omitidos.length) {
  console.warn(
    `Período ${periodoObjetivo}: encabezados omitidos: ${omitidos.join('; ')}`
  );
}

if (!Object.keys(resultado).length) {
  console.log(
    `Período ${periodoObjetivo}: sin celdas válidas nuevas para escribir`
  );
  return [];
}

resultado[encabezadoPeriodo] = filaActual[encabezadoPeriodo];

return [{ json: resultado }];
